create type public.app_role as enum ('admin','user');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated;
grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy "Read own roles" on public.user_roles for select to authenticated using(user_id=auth.uid());
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke all on function public.has_role(uuid,public.app_role) from public;
grant execute on function public.has_role(uuid,public.app_role) to authenticated;
create function public.assign_shop_owner() returns trigger language plpgsql security definer set search_path=public as $$ begin if lower(new.email)='karthickkumaravel555@gmail.com' and new.email_confirmed_at is not null and exists(select 1 from auth.identities where user_id=new.id and provider in ('google','lovable')) then insert into public.user_roles(user_id,role) values(new.id,'admin') on conflict do nothing; end if; return new; end $$;
create trigger assign_shop_owner_after_confirmation after insert or update of email_confirmed_at on auth.users for each row execute function public.assign_shop_owner();
create function public.assign_shop_identity_owner() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.user_roles(user_id,role) select u.id,'admin'::public.app_role from auth.users u where u.id=new.user_id and lower(u.email)='karthickkumaravel555@gmail.com' and u.email_confirmed_at is not null and new.provider in ('google','lovable') on conflict do nothing; return new; end $$;
create trigger assign_shop_identity_owner after insert on auth.identities for each row execute function public.assign_shop_identity_owner();
create table public.products (id text primary key, kind text not null check(kind in ('phone','accessory')), brand text not null, name text not null, price integer not null check(price>=0), mrp integer not null check(mrp>=price), category text, specs text[] not null default '{}', description text not null default '', rating numeric not null default 0 check(rating>=0 and rating<=5), hue integer not null default 230, image_url text, created_at timestamptz not null default now());
grant select on public.products to anon;
grant select,insert,update,delete on public.products to authenticated;
grant all on public.products to service_role;
alter table public.products enable row level security;
create policy "Public catalog" on public.products for select to anon,authenticated using(true);
create policy "Owner inserts" on public.products for insert to authenticated with check(public.has_role(auth.uid(),'admin'));
create policy "Owner updates" on public.products for update to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create policy "Owner deletes" on public.products for delete to authenticated using(public.has_role(auth.uid(),'admin'));
create policy "Public product photos" on storage.objects for select to anon,authenticated using(bucket_id='product-photos');
create policy "Owner uploads photos" on storage.objects for insert to authenticated with check(bucket_id='product-photos' and public.has_role(auth.uid(),'admin'));
create policy "Owner removes photos" on storage.objects for delete to authenticated using(bucket_id='product-photos' and public.has_role(auth.uid(),'admin'));